import { spawn } from 'node:child_process';
import path from 'node:path';
import { z } from 'zod';

import { getGithubActionsWriteToken, type AgentWriteToken } from './agent-deployment.js';
import { AgentApiError } from './agent-http.js';
import { agentSiteUrl } from './deploy.js';

const oidcSchema = z.object({ value: z.string().min(1) });

export type GithubActionsDeployOptions = {
  apiUrl: string;
  directory: string;
  subdomain?: string;
};

export function isGithubActions(env: NodeJS.ProcessEnv = process.env): boolean {
  return env.GITHUB_ACTIONS === 'true';
}

async function getGithubOidcToken(env: NodeJS.ProcessEnv, audience: string): Promise<string> {
  const requestUrl = env.ACTIONS_ID_TOKEN_REQUEST_URL;
  const requestToken = env.ACTIONS_ID_TOKEN_REQUEST_TOKEN;
  if (!requestUrl || !requestToken) {
    throw new Error(
      'GitHub Actions did not provide an OIDC token. Add `permissions: id-token: write` to the workflow or job.'
    );
  }
  let response: Response;
  try {
    response = await fetch(`${requestUrl}&audience=${encodeURIComponent(audience)}`, {
      headers: { Authorization: `Bearer ${requestToken}` },
      signal: AbortSignal.timeout(30_000),
    });
  } catch {
    throw new Error('Could not request a GitHub Actions OIDC token. Retry the workflow.');
  }
  const parsed = oidcSchema.safeParse(await response.json().catch(() => null));
  if (!response.ok || !parsed.success) {
    throw new Error(
      `Could not get a GitHub Actions OIDC token (HTTP ${response.status}). Check that the workflow has \`permissions: id-token: write\`.`
    );
  }
  return parsed.data.value;
}

function git(args: string[], cwd: string, env: NodeJS.ProcessEnv): Promise<string> {
  return new Promise((resolve, reject) => {
    const child = spawn('git', args, { cwd, env, stdio: ['ignore', 'pipe', 'inherit'] });
    let out = '';
    child.stdout.on('data', (chunk: Buffer) => (out += chunk.toString()));
    child.on('error', reject);
    child.on('close', (code) =>
      code === 0 ? resolve(out.trim()) : reject(new Error(`git ${args[0]} failed`))
    );
  });
}

async function commitDirectory(directory: string, env: NodeJS.ProcessEnv): Promise<string> {
  const prefix = await git(['rev-parse', '--show-prefix'], directory, env);
  const tree = await git(['rev-parse', `HEAD:${prefix}`], directory, env);
  const [name = '', email = '', date = '', sha = '', subject = ''] = (
    await git(['log', '-1', '--format=%an%n%ae%n%aI%n%H%n%s'], directory, env)
  ).split('\n');
  const repository = env.GITHUB_REPOSITORY ? `${env.GITHUB_REPOSITORY}@` : '';
  return git(
    ['commit-tree', tree, '-m', subject, '-m', `Deployed from ${repository}${sha}`],
    directory,
    {
      ...env,
      GIT_AUTHOR_NAME: name,
      GIT_AUTHOR_EMAIL: email,
      GIT_AUTHOR_DATE: date,
      GIT_COMMITTER_NAME: name,
      GIT_COMMITTER_EMAIL: email,
    }
  );
}

function pushCommit(
  directory: string,
  commit: string,
  write: AgentWriteToken,
  env: NodeJS.ProcessEnv
): Promise<void> {
  const index = Number(env.GIT_CONFIG_COUNT) || 0;
  const credentials = Buffer.from(`x-access-token:${write.token}`).toString('base64');
  return new Promise((resolve, reject) => {
    const child = spawn(
      'git',
      ['push', '--force', write.remote, `${commit}:refs/heads/${write.branch}`],
      {
        cwd: directory,
        stdio: ['ignore', 'inherit', 'inherit'],
        env: {
          ...env,
          GIT_CONFIG_COUNT: String(index + 1),
          [`GIT_CONFIG_KEY_${index}`]: `http.${write.remote}.extraHeader`,
          [`GIT_CONFIG_VALUE_${index}`]: `Authorization: Basic ${credentials}`,
        },
      }
    );
    const failed = () => reject(new Error('git push to the site repository failed.'));
    child.on('error', failed);
    child.on('close', (code) => (code === 0 ? resolve() : failed()));
  });
}

export async function deployFromGithubActions(
  options: GithubActionsDeployOptions,
  progress: (message: string) => void = () => {},
  env: NodeJS.ProcessEnv = process.env
): Promise<string> {
  const { apiUrl, subdomain } = options;
  if (!subdomain) throw new Error('Pass the site name with --subdomain <name>.');
  const directory = path.resolve(options.directory);
  const commit = await commitDirectory(directory, env).catch(() => {
    throw new Error(
      `Could not read ${options.directory} from the checked-out commit. Run mint deploy after actions/checkout, with --directory inside the repository.`
    );
  });
  progress('Requesting a GitHub Actions identity token...');
  const oidcToken = await getGithubOidcToken(env, apiUrl);
  progress('Getting repository write access...');
  let write: AgentWriteToken;
  try {
    write = await getGithubActionsWriteToken(apiUrl, oidcToken, subdomain);
  } catch (error) {
    if (error instanceof AgentApiError && error.status === 403) {
      throw new Error(
        `This repository/branch isn't trusted to deploy ${subdomain}. Run \`mint deploy --github\` locally from this repository to trust it.`
      );
    }
    throw error;
  }
  progress('Pushing to the site repository...');
  await pushCommit(directory, commit, write, env);
  return agentSiteUrl(apiUrl, subdomain);
}
